    const entries=[...record.entries].sort((a,b)=>Number(b.type==='tree')-Number(a.type==='tree')||a.name.localeCompare(b.name));
    const selectedIndex=entries.findIndex(entry=>entry.path===ctx.path||ctx.path.startsWith(entry.path+'/'));
