    if (tab === 'security') return `<header class="page-head"><h1>Security overview</h1></header><div class="notice">${icon('shield')}Security services are not connected to this local preview.</div><div class="panel"><div class="workflow-row">${icon('shield')}<div><strong>Security policy</strong><small>No SECURITY.md file has been added to this repository.</small></div></div><div class="workflow-row">${icon('lock')}<div><strong>Private vulnerability reporting</strong><small>Not configured</small></div></div><div class="workflow-row">${icon('code-square')}<div><strong>Code scanning</strong><small>Not configured</small></div></div></div>`;
